(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.015+t*0.4)*20 + Math.cos(y*0.012-t*0.3)*15 + Math.sin((x+y)*0.008+t*0.2)*10;
  const wy = Math.cos(y*0.015-t*0.35)*20 + Math.sin(x*0.013+t*0.25)*15 + Math.cos((x-y)*0.009-t*0.15)*10;
  const sx = x + wx, sy = y + wy;
  const wells = [
    [160+Math.sin(t*0.5)*120, 80+Math.cos(t*0.35)*60, 0.07, 2.5, 1.2],
    [320+Math.cos(t*0.45)*100, 160+Math.sin(t*0.6)*70, 0.09, 2.0, 1.5],
    [240+Math.sin(t*0.25+2)*150, 120+Math.cos(t*0.4+1)*100, 0.05, 3.0, 0.8],
    [100+Math.cos(t*0.7+1)*90, 190+Math.sin(t*0.5+3)*70, 0.11, 1.8, 1.8],
    [380+Math.sin(t*0.35+4)*100, 50+Math.cos(t*0.8+2)*80, 0.06, 2.8, 1.0],
    [200+Math.cos(t*0.3+5)*130, 210+Math.sin(t*0.45)*90, 0.08, 2.2, 1.3]
  ];
  let aS = 0, iS = 0, potential = 0;
  for (const [wX, wY, f, sp, mass] of wells) {
    const dx = sx-wX, dy = sy-wY;
    const d = Math.sqrt(dx*dx + dy*dy) + 1;
    aS += Math.sin(d*f - t*sp) * mass;
    iS += Math.sin(d*f*0.6 + t*sp*0.5 + 2.0) * mass;
    potential += mass / (d * 0.1);
  }
  const act = aS/6, inh = iS/6;
  const bg = (Math.sin(sx*0.035+sy*0.028+t*0.9) + Math.sin(sx*0.028-sy*0.035+t*1.3))/2 + Math.sin((sx+sy)*0.11+t*2.8)*0.25 + Math.sin((sx-sy)*0.09-t*2.2)*0.25;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.045-ang*4-t*1.8) + Math.sin(dist*0.035+ang*5-t*1.4))*0.5;
  const kinetic = Math.sin(dist*0.03 - t*2.0 + ang*2) * 0.3;
  const conversion = Math.tanh((act - inh*0.6 + bg*0.25 + spiral + kinetic)*2.8);
  const cell = Math.tanh((Math.sin(sx*0.13)*Math.sin(sy*0.13) + Math.sin((sx+sy)*0.09+t*0.8)*0.6)*1.8)*0.25;
  const blend = conversion*0.8 + cell*0.2, v = blend*0.5+0.5;
  const pal = [[2,4,15],[5,15,50],[0,60,120],[0,180,255],[0,255,200],[150,255,100],[255,220,50],[255,100,150],[255,50,100],[180,30,80],[60,10,40],[2,4,15]];
