  const lum = (0.7+Math.sin(conversion*Math.PI)*0.3)*edge*(0.6+glow*0.6);
  const bloom = Math.max(0, conversion-0.5)*2.0;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum+bloom*40)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum+bloom*80)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum+bloom*120)|0)
  ];
}
